/bin/bash -lc "cat > /tmp/generate.py <<'PY'
from pathlib import Path
for flavor,prefix in [('classic','Zod'),('mini','ZodMini')]:
 p=Path(f'packages/zod/src/v4/{flavor}/deep-partial.ts')
 code='''import * as core from \"../core/index.js\";
import { visit } from \"../core/visit.js\";
import * as schemas from \"./schemas.js\";

type Mode = \"partial\" | \"input\" | \"output\";
type Shape<S extends core."'$ZodShape, M extends Mode> = {
  [K in keyof S]: M extends "partial" ? schemas.POptional<Tree<S[K], M>> : Tree<S[K], M>;
};
export type Tree<T extends core.SomeType, M extends Mode> =
  T extends schemas.PObject<infer S, infer C> ? schemas.PObject<Shape<S, M>, C> :
  T extends schemas.PCodec<infer A, infer B> ? M extends "input" ? Tree<A, M> : M extends "output" ? Tree<B, M> : schemas.PCodec<Tree<A, M>, Tree<B, M>> :
  T extends schemas.PPreprocess<infer B, infer I> ? M extends "input" ? Tree<T["_zod"]["def"]["in"], M> : M extends "output" ? Tree<B, M> : schemas.PPreprocess<Tree<B, M>, I> :
  T extends schemas.PPipe<infer A, infer B> ? M extends "input" ? Tree<A, M> : M extends "output" ? Tree<B, M> : schemas.PPipe<Tree<A, M>, Tree<B, M>> :
'"'''
 for name in ['Array','Optional','Nullable','Default','Prefault','NonOptional','Catch','Readonly','Promise','Success','Lazy','Set']:
  code+=f'  T extends schemas.P{name}<infer I> ? schemas.P{name}<Tree<I, M>> :\\n'
 for name in ['Record','Map','Intersection']:
  code+=f'  T extends schemas.P{name}<infer A, infer B> ? schemas.P{name}<Tree<A, M>, Tree<B, M>> :\\n'
 code+='''  T extends schemas.PTuple<infer I, infer R> ? schemas.PTuple<{ [K in keyof I]: Tree<I[K], M> }, R extends core.SomeType ? Tree<R, M> : null> :
  T extends schemas.PUnion<infer O> ? schemas.PUnion<{ [K in keyof O]: Tree<O[K], M> }> :
  T;

/** Make every object in a schema tree partial. */
export function deepPartial<T extends core.SomeType>(schema: T): Tree<T, \"partial\"> {
  return visit(schema, {
    object: (node) => {
      const shape: core."'$ZodShape = {};
      for (const key of Object.keys(node._zod.def.shape)) {
        Object.defineProperty(shape, key, { enumerable: true, get: () => schemas.optional(node._zod.def.shape[key]) });
      }
      return core.clone(node, { ...node._zod.def, shape });
    },
    union: (node) => node._zod.def.discriminator === undefined ? node : schemas.union(node._zod.def.options),
  }) as Tree<T, "partial">;
}

/** Select the input side of every pipe in a schema tree. */
export function input<T extends core.SomeType>(schema: T): Tree<T, "input"> {
  return visit(schema, { pipe: (node) => node._zod.def.in }) as Tree<T, "input">;
}

/** Select the output side of every pipe in a schema tree. */
export function output<T extends core.SomeType>(schema: T): Tree<T, "output"> {
  return visit(schema, { pipe: (node) => node._zod.def.out }) as Tree<T, "output">;
}
'"'''
 code=code.replace('schemas.P','schemas.'+prefix)
 p.write_text(code)
 ext=Path(f'packages/zod/src/v4/{flavor}/external.ts')
 s=ext.read_text().replace('export type { infer, output, input } from \"../core/index.js\";', 'export type { infer } from \"../core/index.js\";\\nexport { deepPartial, input, output } from \"./deep-partial.js\";')
 # merge type/value names in same module
 p.write_text(p.read_text()+'\\nexport type input<T> = core.input<T>;\\nexport type output<T> = core.output<T>;\\n')
 ext.write_text(s.replace('export { deepPartial, input, output }','export { deepPartial, input, output }'))
PY
python3 /tmp/generate.py
pnpm exec tsc --noEmit --pretty false > /tmp/ts-errors 2>&1"

